WITH src AS (SELECT * FROM transactions WHERE amount < 1900), summary AS (SELECT CASE WHEN amount >= 3800 THEN 'high' WHEN amount >= 1000 THEN 'mid' ELSE 'low' END AS amount_bucket, COUNT(amount) AS amount_count, SUM(amount) AS total_amount FROM src GROUP BY CASE WHEN amount >= 3800 THEN 'high' WHEN amount >= 1000 THEN 'mid' ELSE 'low' END) SELECT amount_bucket, amount_count, total_amount FROM summary WHERE total_amount >= 17000 ORDER BY amount_count DESC
